    faq_rosetta_deb_a_post="que Ubuntu. Activa Rosetta para el espacio de trabajo en su pestaña Recursos, inícialo, y luego ejecuta esto una vez dentro del invitado:",
    faq_rosetta_deb_code="sudo mkdir -p /media/rosetta\nsudo mount -t virtiofs rosetta /media/rosetta\n\nsudo apt-get update\nsudo apt-get install -y binfmt-support\n\nsudo /usr/sbin/update-binfmts --install rosetta /media/rosetta/rosetta \\\n  --magic \"\\x7fELF\\x02\\x01\\x01\\x00\\x00\\x00\\x00\\x00\\x00\\x00\\x00\\x00\\x02\\x00\\x3e\\x00\" \\\n  --mask \"\\xff\\xff\\xff\\xff\\xff\\xfe\\xfe\\x00\\xff\\xff\\xff\\xff\\xff\\xff\\xff\\xff\\xfe\\xff\\xff\\xff\" \\\n  --credentials yes --preserve yes --fix-binary yes",
